// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Fund the contract with 1 wei
        vm.deal(address(c), 1 wei);
        // Get owner address
        address owner = c.owner();
        uint256 ownerBalBefore = owner.balance;
        // Call go() with 0 ether from any random account
        vm.prank(address(0xABCD));
        c.go();
        // The divergence: in reference, the 1 wei is transferred to owner; in mutant, it's sent to target (0xC8A...)
        // So after go(), owner's balance should be ownerBalBefore + 1 in reference, but unchanged in mutant.
        assertTrue(owner.balance == ownerBalBefore + 1 wei);
    }
}

