pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address owner = c.owner();
        uint256 initialOwnerBalance = owner.balance;

        // Give the contract 1 wei from a non-owner
        address nonOwner = address(0x1234);
        vm.deal(nonOwner, 1 wei);
        vm.prank(nonOwner);
        (bool sent, ) = address(c).call{value: 1 wei}("");
        require(sent);

        // Owner calls go() with 1 wei, total contract balance becomes 2 wei
        vm.deal(owner, 1 wei);
        vm.prank(owner);
        c.go{value: 1 wei}();

        // In the reference, the full 2 wei are sent to owner; in buggy, sent to target (not owner)
        uint256 ownerIncrease = owner.balance - initialOwnerBalance;
        assertTrue(ownerIncrease == 2 wei, "Owner should have gained 2 wei");
    }
}

