pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address nonOwner = address(0x1234);
        address owner = c.owner();
        // Non-owner sends 1 wei to the contract via fallback
        vm.deal(nonOwner, 1 wei);
        vm.prank(nonOwner);
        (bool sent, ) = address(c).call{value: 1 wei}("");
        require(sent, "fallback failed");
        // Owner calls go() with 0 value and 1 wei of ether (the msg.value is 0)
        vm.deal(owner, 1 wei);
        vm.prank(owner);
        (bool ok, ) = address(c).call(abi.encodeWithSignature("go()"));
        require(ok, "go() reverted");
        // After go(): reference sends contract balance (1 wei) to owner, buggy sends to target which reverts, leaving 1 wei
        bool balanceZero = (address(c).balance == 0 wei);
        assertTrue(balanceZero);
    }
}

