pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address owner = c.owner();
        address nonOwner = address(0x1234);

        // Owner deposits 1 wei to create initial balance
        vm.deal(owner, 1 wei);
        vm.prank(owner);
        c.go{value: 1 wei}();

        // Owner balance after first call: previous balance + 1 wei back
        // Contract balance should be 0

        // Now non-owner sends 1 wei – reference forwards to owner, bug reverts
        vm.deal(nonOwner, 1 wei);
        vm.prank(nonOwner);
        bool ok;
        try c.go{value: 1 wei}() {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference: call succeeds, contract balance 0
        // Bug: call reverts, contract balance 2 (owner deposit stayed + this deposit)
        assertTrue(address(c).balance == 0);
    }
}

